PP4=timerange('2010-01-01','2010-03-29');
ZEP_rd2.BsG_S13(PP4)=ZEP_rd2.BsG_S11(PP3);
ZEP_rd2.BsB_S13(PP4)=ZEP_rd2.BsB_S11(PP3) %[output:1315ac31]
